.study-radio-group {
    display: inline-block
}

.study-radio-group label {
    font-weight: 400;
    padding-left: 25px;
    padding-right: 15px;
    position: relative;
    cursor: pointer
}

.study-radio-group [type=radio]:checked,.study-radio-group [type=radio]:not(:checked) {
    position: absolute;
    left: -9999px
}

.study-radio-group label>[type=radio]:checked+span:before,.study-radio-group label>[type=radio]:not(:checked)+span:before {
    content: '';
    position: absolute;
    left: 0;
    top: 0;
    width: 18px;
    height: 18px;
    border: 1px solid #ddd;
    border-radius: 100%;
    background: #fff
}

.study-radio-group label>[type=radio]:checked+span:after,.study-radio-group label>[type=radio]:not(:checked)+span:after {
    content: '';
    width: 10px;
    height: 10px;
    background: #0096b2;
    position: absolute;
    top: 4px;
    left: 4px;
    border-radius: 100%;
    -webkit-transition: .2s;
    transition: .2s
}

.study-radio-group label>[type=radio]:not(:checked)+span:after {
    opacity: 0;
    -webkit-transform: scale(0);
    transform: scale(0)
}

.study-radio-group label>[type=radio]:checked+span:after {
    opacity: 1;
    -webkit-transform: scale(1);
    transform: scale(1)
}

.study-checkbox-group {
    display: inline-block
}

.study-checkbox-group label {
    font-weight: 400;
    padding-left: 25px;
    padding-right: 15px;
    position: relative;
    cursor: pointer
}

.study-checkbox-group [type=checkbox]:checked,.study-checkbox-group [type=checkbox]:not(:checked) {
    position: absolute;
    left: -1px;
    top: -1px;
    width: auto;
    transform: scale(0);
    box-shadow: none
}

.study-checkbox-group label>[type=checkbox]:checked+span:before,.study-checkbox-group label>[type=checkbox]:not(:checked)+span:before {
    content: '';
    position: absolute;
    left: 0;
    top: 0;
    width: 18px;
    height: 18px;
    border: 1px solid #ddd;
    border-radius: 4px;
    background: #fff
}

.study-checkbox-group label>[type=checkbox]:checked+span:after,.study-checkbox-group label>[type=checkbox]:not(:checked)+span:after {
    font-family: Icomoon;
    content: "\e94d";
    font-size: 27px;
    color: #0096b2;
    position: absolute;
    top: -9px;
    left: -4px;
    border-radius: 100%;
    -webkit-transition: .2s;
    transition: .2s
}

.study-checkbox-group label>[type=checkbox]:not(:checked)+span:after {
    opacity: 0;
    -webkit-transform: scale(0);
    transform: scale(0);
    transform-origin: 50% 50%
}

.study-checkbox-group label>[type=checkbox]:checked+span:after {
    opacity: 1;
    -webkit-transform: scale(1);
    transform: scale(1);
    transform-origin: 50% 50%
}

