.confetti-explosion {
    position: relative
}

.confetti-explosion .confetti-explosion__particle {
    position: absolute;
    top: 40%;
    left: 50%;
    opacity: 0;
    z-index: -1
}

.confetti-explosion .confetti-explosion__particle:before {
    content: '';
    display: block
}

.confetti-explosion .confetti-explosion__particle:nth-child(3n):before {
    width: 6px;
    height: 6px;
    background: #fab323
}

.confetti-explosion .confetti-explosion__particle:nth-child(3n+1):before {
    border-style: solid;
    border-color: #bf2867 transparent transparent;
    border-width: 6px 4px 0
}

.confetti-explosion .confetti-explosion__particle:nth-child(3n+2):before {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #0096b2
}

.confetti-explosion.exploding .confetti-explosion__particle {
    opacity: 1;
    -webkit-animation-name: confettiParticle;
    animation-name: confettiParticle;
    -webkit-animation-delay: inherit;
    animation-delay: inherit;
    -webkit-animation-duration: 2s;
    animation-duration: 2s;
    -webkit-animation-fill-mode: both;
    animation-fill-mode: both
}

@keyframes confettiParticle {
    0% {
        transform: translate(0,0) rotate(0);
        opacity: 0
    }

    1%,70% {
        opacity: 1
    }

    30% {
        top: 20%
    }

    100% {
        top: 60%;
        opacity: 0
    }
}

@-webkit-keyframes confettiParticle {
    0% {
        transform: translate(0,0) rotate(0);
        opacity: 0
    }

    1%,70% {
        opacity: 1
    }

    30% {
        top: 20%
    }

    100% {
        top: 60%;
        opacity: 0
    }
}

